function renderBoard() {
  const cols = ['unread', 'reading', 'read', 'reviewed'];
  $('#view').innerHTML =
    '<section data-od-id="board-view">' +
      '<div class="sec-head"><div><span class="eyebrow">阅读阶段</span><h2 class="h2" style="margin-top:6px;font-size:22px">拖动卡片推进阅读进度</h2></div>' +
      '<span class="meta">共 ' + papers().length + ' 篇</span></div>' +
      '<div class="board">' + cols.map(k => {
        const items = papers().filter(p => S.get(p) === k).sort((a, b) => b.upd.localeCompare(a.upd));
        return '<div class="col" data-col="' + k + '">' +
          '<div class="col-head"><span class="ch-dot" style="background:' + STATUS[k].color + '"></span><span class="ch-n">' + STATUS[k].label + '</span><span class="ch-c">' + items.length + '</span></div>' +
          items.map(p => {
            const cv = CONV[p.cv];
            return '<div class="kcard" draggable="true" data-id="' + p.id + '">' +
              '<div class="kc-t">' + esc(p.title) + '</div>' +
              '<div class="kc-m">' + p.venue + ' ' + p.year + ' · ' + (activePlan().progress[p.id] || 0) + '%</div>' +
              '<div class="kc-foot"><span class="tag">' + p.tags[0] + '</span><span class="kc-conv ' + cv.cls + '" style="margin-left:auto">' + cv.label + '</span></div>' +
            '</div>';
          }).join('') + '</div>';
      }).join('') + '</div>' +
    '</section>';

  let dragId = null;
  $$('#view .kcard').forEach(card => {
    card.addEventListener('dragstart', e => { dragId = card.dataset.id; card.classList.add('is-drag'); e.dataTransfer.effectAllowed = 'move'; try { e.dataTransfer.setData('text/plain', dragId); } catch (x) {} });
    card.addEventListener('dragend', () => card.classList.remove('is-drag'));
    card.addEventListener('click', () => openPaper(card.dataset.id));
  });
  $$('#view .col').forEach(col => {
    col.addEventListener('dragover', e => { e.preventDefault(); col.classList.add('is-over'); });
    col.addEventListener('dragleave', () => col.classList.remove('is-over'));
    col.addEventListener('drop', e => {
      e.preventDefault(); col.classList.remove('is-over');
      const id = dragId || e.dataTransfer.getData('text/plain');
      if (!id) return;
      S.set(id, col.dataset.col);
      if (col.dataset.col === 'read' || col.dataset.col === 'reviewed') activePlan().progress[id] = Math.max(activePlan().progress[id] || 0, 100);
      save(); renderShell(); renderBoard();
      toast('已移至「' + STATUS[col.dataset.col].label + '」');
    });
  });
}

